#[no_mangle]
pub unsafe extern "C" fn minimum_tickets_cost(v:*const i64,n:usize)->i64{if v.is_null()||n<4||n>369{return -1}let a=std::slice::from_raw_parts(v,n);if a[0]<0||a[0]>365{return -1}let d=a[0] as usize;if n!=d+4{return -1}let mut travel=[false;366];for &x in &a[1..d+1]{if !(1..=365).contains(&x)||travel[x as usize]{return -1}travel[x as usize]=true}let costs=&a[d+1..];if costs.iter().any(|&x|!(0..=1_000_000).contains(&x)){return -1}let mut dp=[0i64;397];for day in (1..=365).rev(){dp[day]=dp[day+1];if travel[day]{dp[day]=(costs[0]+dp[day+1]).min(costs[1]+dp[day+7]).min(costs[2]+dp[day+30]);}}dp[1]}
